// @FIGURE_CODE_BEGIN
var W = 640, H = 340;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

var Px = 112, roadY = 250, TOPY = 50;
var TEAL = '#159e94', GRAY = '#8c8c8c', INK = '#111', ORANGE = '#e8820c';
var GROUND_A = 2.5 / Math.tan(49 * Math.PI / 180);   // fixed ground leg plane→A (miles)
var PHASES = ['horizontal reference', 'two right triangles', 'label unknowns', 'write equations'];
var state = { h: 2.5, ab: 3.2, phase: 0 };

/* ---------- small helpers ---------- */
function bindEl(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  if (title) el.on('click', function () { showPopup(title, body); });
  return el;
}
function hitLine(x1, y1, x2, y2, tip, title, body) {
  var h = draw.line(x1, y1, x2, y2).stroke({ color: '#000', width: 16, opacity: 0 })
    .attr('pointer-events', 'all');
  return bindEl(h, tip, title, body);
}
function halo(t) {
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.4, 'stroke-linejoin': 'round' });
  return t;
}
function label(txt, x, y, color, size, anchor, italic) {
  var t = draw.text(txt).font({
    family: 'Georgia, "Times New Roman", serif',
    size: size || 14, anchor: anchor || 'middle',
    style: italic ? 'italic' : 'normal'
  }).fill(color || INK);
  t.center(x, y);
  if (anchor === 'start') { t.attr('text-anchor', 'start'); t.x(x); }
  if (anchor === 'end') { t.attr('text-anchor', 'end'); t.x(x - t.bbox().width); }
  return halo(t);
}
function arcPath(cx, cy, r, ang) {
  var x0 = cx + r, y0 = cy;
  var x1 = cx + r * Math.cos(ang), y1 = cy + r * Math.sin(ang);
  return 'M ' + x0 + ' ' + y0 + ' A ' + r + ' ' + r + ' 0 0 1 ' + x1 + ' ' + y1;
}
function bracket(x1, x2, y, txt, color, tip, title, body) {
  var g = draw.group();
  g.line(x1, y, x2, y).stroke({ color: color, width: 1.2 });
  g.line(x1, y - 4, x1, y + 4).stroke({ color: color, width: 1.2 });
  g.line(x2, y - 4, x2, y + 4).stroke({ color: color, width: 1.2 });
  var t = label(txt, (x1 + x2) / 2, y + 13, color, 13, 'middle', true);
  bindEl(g, tip, title, body); bindEl(t, tip, title, body);
  return g;
}

/* ---------- airplane icon (nose left, vertex at tail) ---------- */
function drawPlane(x, y) {
  var g = draw.group();
  function P(pts, fill) { return g.polygon(pts).fill(fill).stroke({ color: '#2c3a63', width: 0.8 }); }
  g.ellipse(98, 23).move(x - 98, y - 16).fill('#c3cde2').stroke({ color: '#3c4c7d', width: 1.1 });
  P([[x - 56, y - 8], [x - 34, y - 23], [x - 23, y - 23], [x - 38, y - 8]], '#5d6d9c');
  P([[x - 14, y - 9], [x - 3, y - 31], [x + 5, y - 31], [x + 1, y - 7]], '#3c4c7d');
  P([[x - 6, y - 9], [x + 6, y - 17], [x + 14, y - 17], [x + 3, y - 7]], '#5d6d9c');
  P([[x - 52, y - 1], [x - 27, y + 14], [x - 13, y + 14], [x - 33, y - 1]], '#3c4c7d');
  g.rect(15, 7).radius(3).move(x - 46, y + 2).fill('#2c3a63');
  g.circle(6).center(x - 89, y - 9).fill('#2b3a63');
  g.line(x - 80, y - 7, x - 34, y - 7).stroke({ color: '#8f9cbd', width: 1, dasharray: '2,3' });
  g.circle(4.5).center(x, y).fill(INK);
  bindEl(g, 'The observer: every sight line starts here',
    'One observer, two sightings',
    'Both lines of sight leave the same airplane, so both right triangles share the same vertical leg h. That shared altitude is the bridge that links the two depression angles to the distances on the ground.');
  return g;
}

/* ---------- main render ---------- */
function render() {
  draw.clear();
  var xMax = GROUND_A + state.ab;
  var s = Math.min((W - 36 - Px) / xMax, (roadY - TOPY) / state.h);
  var PY = roadY - state.h * s;
  var Ax = Px + GROUND_A * s, Bx = Px + xMax * s;
  var aA = Math.atan(state.h / GROUND_A), aB = Math.atan(state.h / xMax);
  var degA = aA * 180 / Math.PI, degB = aB * 180 / Math.PI;
  var dA = Math.sqrt(state.h * state.h + GROUND_A * GROUND_A);
  var dB = Math.sqrt(state.h * state.h + xMax * xMax);
  var ph = state.phase;

  /* shaded right triangles */
  if (ph >= 1) {
    draw.polygon([[Px, PY], [Px, roadY], [Bx, roadY]]).fill({ color: TEAL, opacity: 0.07 });
    draw.polygon([[Px, PY], [Px, roadY], [Ax, roadY]]).fill({ color: ORANGE, opacity: 0.11 });
  }

  /* highway */
  draw.line(40, roadY, W - 18, roadY).stroke({ color: INK, width: 2.2 });
  hitLine(40, roadY, W - 18, roadY, 'The straight highway (ground level)',
    'The highway', 'A and B are two mileposts on one straight road. The only length that is actually known in this problem is the gap AB between them.');

  /* teal horizontal reference */
  draw.line(Px, PY, W - 16, PY).stroke({ color: TEAL, width: 1.9, dasharray: '7,5' });
  hitLine(Px, PY, W - 16, PY, 'Horizontal reference through the airplane',
    'Angles of depression start here',
    'An angle of depression is measured downward from the horizontal line through the observer — never up from the ground. This teal dashed line is that horizontal reference.');

  /* sight lines */
  draw.line(Px, PY, Ax, roadY).stroke({ color: GRAY, width: 1.6, dasharray: '6,4' });
  draw.line(Px, PY, Bx, roadY).stroke({ color: GRAY, width: 1.6, dasharray: '6,4' });
  hitLine(Px, PY, Ax, roadY, 'Line of sight to A — slant distance ' + dA.toFixed(2) + ' mi',
    'Steeper sighting (to A)', 'A is nearer, so the eye must look down more steeply: the depression angle to A is the larger of the two, currently ' + degA.toFixed(1) + '°.');
  hitLine(Px, PY, Bx, roadY, 'Line of sight to B — slant distance ' + dB.toFixed(2) + ' mi',
    'Shallower sighting (to B)', 'B is farther along the road, so its sight line is flatter and its depression angle smaller — currently ' + degB.toFixed(1) + '°. Only this angle changes when you slide B away.');

  /* angle arcs */
  var rB = 36, rA = 60;
  var arcB = draw.path(arcPath(Px, PY, rB, aB)).fill('none').stroke({ color: INK, width: 1.1 });
  var arcA = draw.path(arcPath(Px, PY, rA, aA)).fill('none').stroke({ color: INK, width: 1.1 });
  bindEl(arcB, 'Depression angle to B = ' + degB.toFixed(1) + '°', 'The 25° angle',
    'Measured from the teal horizontal down to the far sight line. In the right triangle with legs h and x + AB, tan(this angle) = h / (x + AB).');
  bindEl(arcA, 'Depression angle to A = ' + degA.toFixed(1) + '°', 'The 49° angle',
    'Measured from the teal horizontal down to the near sight line. In the small right triangle with legs h and x, tan(this angle) = h / x.');

  var mB = aB / 2, mA = (aA + aB) / 2;
  var tB = label(degB.toFixed(0) + '°', Px + (rB + 18) * Math.cos(mB), PY + (rB + 18) * Math.sin(mB), INK, 14);
  var tA = label(degA.toFixed(0) + '°', Px + (rA + 16) * Math.cos(mA), PY + (rA + 16) * Math.sin(mA), INK, 14);
  bindEl(tB, 'Depression angle to B = ' + degB.toFixed(1) + '°');
  bindEl(tA, 'Depression angle to A = ' + degA.toFixed(1) + '°');

  /* altitude + right angle */
  if (ph >= 1) {
    draw.line(Px, PY, Px, roadY).stroke({ color: ORANGE, width: 1.6, dasharray: '5,4' });
    hitLine(Px, PY, Px, roadY, 'Shared vertical leg h = ' + state.h.toFixed(1) + ' mi',
      'The shared altitude', 'Dropping a perpendicular to the road creates two right triangles that share this one vertical leg. Because h is common to both, two sightings are enough to determine it.');
    draw.polyline([[Px + 12, roadY], [Px + 12, roadY - 12], [Px, roadY - 12]])
      .fill('none').stroke({ color: '#444', width: 1.1 });
    bindEl(label('h', Px - 9, (PY + roadY) / 2, ORANGE, 15, 'end', true),
      'h = ' + state.h.toFixed(1) + ' mi (unknown in the real problem)');
  }

  /* road points */
  draw.circle(6).center(Ax, roadY).fill(INK);
  draw.circle(6).center(Bx, roadY).fill(INK);
  bindEl(label('A', Ax, roadY + 15, INK, 16, 'middle', true), 'Milepost A');
  bindEl(label('B', Bx, roadY + 15, INK, 16, 'middle', true), 'Milepost B');

  /* unknown labels */
  if (ph >= 2) {
    bracket(Px, Ax, roadY + 30, 'x', ORANGE,
      'x = horizontal leg of the small triangle (unknown)',
      'Naming the near leg', 'Call the horizontal distance from the point beneath the plane to A simply x. It is unknown — everything orange is unknown.');
    bracket(Ax, Bx, roadY + 30, 'AB = ' + state.ab.toFixed(1) + ' mi', INK,
      'AB = ' + state.ab.toFixed(1) + ' mi — the one known length',
      'The known gap', 'The spacing of the two mileposts is the only measured length. It is what ties the small triangle to the large one.');
    bracket(Px, Bx, roadY + 54, 'x + AB', ORANGE,
      'Horizontal leg of the large triangle = x + AB',
      'The far leg', 'The big right triangle has the same height h but a horizontal leg of x + AB, which is why the same altitude produces a smaller depression angle at B.');

    var ux = Ax - Px, uy = roadY - PY, L = Math.hypot(ux, uy); ux /= L; uy /= L;
    var m1x = Px + (Ax - Px) * 0.55, m1y = PY + (roadY - PY) * 0.55;
    bindEl(label('d\u2081', m1x + uy * 17, m1y - ux * 17, ORANGE, 14, 'middle', true),
      'Slant distance plane → A = ' + dA.toFixed(2) + ' mi (unknown)');
    var vx = Bx - Px, vy = roadY - PY, L2 = Math.hypot(vx, vy); vx /= L2; vy /= L2;
    var m2x = Px + (Bx - Px) * 0.62, m2y = PY + (roadY - PY) * 0.62;
    bindEl(label('d\u2082', m2x - vy * 17, m2y + vx * 17, ORANGE, 14, 'middle', true),
      'Slant distance plane → B = ' + dB.toFixed(2) + ' mi (unknown)');
  }

  /* equation callout */
  if (ph >= 3) {
    var bw = 250, bh = 84, bx = W - 18 - bw;
    var by = Math.max(8, Math.min(PY + 16, roadY - 14 - bh));
    var box = draw.rect(bw, bh).radius(6).move(bx, by)
      .fill({ color: '#ffffff', opacity: 0.94 }).stroke({ color: '#c9ccd2', width: 1 });
    bindEl(box, 'Two equations, two unknowns (h and x)',
      'Solving the system',
      'tan(' + degA.toFixed(0) + '°) = h/x and tan(' + degB.toFixed(0) + '°) = h/(x+AB). Solve each for x, set them equal, and you get h = AB / (cot ' + degB.toFixed(0) + '° − cot ' + degA.toFixed(0) + '°); then x = h / tan ' + degA.toFixed(0) + '° and d₁ = h / sin ' + degA.toFixed(0) + '°.');
    label('tan(' + degA.toFixed(0) + '\u00b0) = h / x', bx + 14, by + 20, ORANGE, 13.5, 'start', true);
    label('tan(' + degB.toFixed(0) + '\u00b0) = h / (x + AB)', bx + 14, by + 43, ORANGE, 13.5, 'start', true);
    label('\u21d2  h = AB / (cot ' + degB.toFixed(0) + '\u00b0 \u2212 cot ' + degA.toFixed(0) + '\u00b0) = ' + state.h.toFixed(2),
      bx + 14, by + 67, INK, 12.5, 'start', false);
  }

  drawPlane(Px, PY);

  var r = document.getElementById('readout');
  if (r) {
    r.innerHTML = 'depression to A <b>' + degA.toFixed(1) + '\u00b0</b> &middot; to B <b>' + degB.toFixed(1) + '\u00b0</b><br>'
      + 'h = ' + state.h.toFixed(1) + ' mi &middot; x = ' + GROUND_A.toFixed(2) + ' mi (A is fixed on the road)<br>'
      + 'slant d\u2081 = ' + dA.toFixed(2) + ' mi &middot; d\u2082 = ' + dB.toFixed(2) + ' mi';
  }
}

/* ---------- interactions ---------- */
function update_altitude(v) { state.h = v; render(); }
function update_abDistance(v) { state.ab = v; render(); }
function trigger_phase() {
  state.phase = (state.phase + 1) % PHASES.length;
  document.getElementById('phaseVal').textContent = PHASES[state.phase];
  render();
}

/* ---------- demo steps ---------- */
var DEMO = [
  { title: 'The horizontal reference', narration: 'Angles of depression are always measured downward from the horizontal through the observer, not from the ground. The teal dashed line is that horizontal; the sight line to A drops 49° below it and the sight line to B only 25°.', state: { phase: 'horizontal reference', altitude: 2.5, abDistance: 3.2 } },
  { title: 'Drop the altitude: two right triangles', narration: 'Dropping a perpendicular from the plane to the highway splits the picture into two right triangles that share the same vertical leg h. The nearer, steeper sighting gives the small triangle; the farther, shallower one gives the large triangle.', state: { phase: 'two right triangles', altitude: 2.5, abDistance: 3.2 } },
  { title: 'Name the unknowns', narration: 'The horizontal leg to A is x, so the horizontal leg to B is x + AB. Only the spacing between the mileposts is known — everything orange is unknown.', state: { phase: 'label unknowns', altitude: 2.5, abDistance: 3.2 } },
  { title: 'Raise the plane', narration: 'Push the altitude up and watch both angles open wider simultaneously. One height controls both triangles, which is precisely why two sightings are enough to pin it down.', state: { phase: 'label unknowns', altitude: 4.2, abDistance: 3.2 } },
  { title: 'Push B down the road', narration: 'Now hold the height fixed and slide B away. Only the far angle changes, collapsing toward the horizontal — the 25° reading is really a statement about how far B is, given the same h.', state: { phase: 'label unknowns', altitude: 2.5, abDistance: 6.5 } },
  { title: 'Two tangents, one system', narration: 'tan(49°) = h/x and tan(25°) = h/(x + AB). Two equations, two unknowns: eliminate x to get h = AB / (cot 25° − cot 49°), then recover the slant distance to A.', state: { phase: 'write equations', altitude: 2.5, abDistance: 3.2 } }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = i;
  var st = DEMO[i].state;
  state.h = st.altitude; state.ab = st.abDistance;
  state.phase = PHASES.indexOf(st.phase);
  document.getElementById('altitudeInput').value = st.altitude;
  document.getElementById('altitudeVal').value = st.altitude;
  document.getElementById('abDistanceInput').value = st.abDistance;
  document.getElementById('abDistanceVal').value = st.abDistance;
  document.getElementById('phaseVal').textContent = st.phase;
  document.getElementById('demoNarration').innerHTML = '<b>' + DEMO[i].title + '</b><br>' + DEMO[i].narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (i + 1) + ' / ' + DEMO.length;
  render();
}
function nextStep() { if (stepIdx < DEMO.length - 1) applyStep(stepIdx + 1); }
function prevStep() { if (stepIdx > 0) applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
